#include <sqlite3.h>
#include "fee_calculator.h"
#include <algorithm>
#include <cctype>
#include <chrono>
#include <cstdint>
#include <ctime>
#include <filesystem>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>

namespace {
class Db {
 sqlite3* db_{};
public:
 explicit Db(const char* path) { if(sqlite3_open(path,&db_)!=SQLITE_OK) throw std::runtime_error(sqlite3_errmsg(db_)); sqlite3_exec(db_,"PRAGMA foreign_keys=ON;",nullptr,nullptr,nullptr); }
 ~Db(){sqlite3_close(db_);} sqlite3* get(){return db_;}
 void exec(const char* q){char* e=nullptr;if(sqlite3_exec(db_,q,nullptr,nullptr,&e)!=SQLITE_OK){std::string s=e?e:"database error";sqlite3_free(e);throw std::runtime_error(s);}}
};
struct Stmt { sqlite3_stmt* p{}; Stmt(sqlite3* d,const char* q){if(sqlite3_prepare_v2(d,q,-1,&p,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(d));} ~Stmt(){sqlite3_finalize(p);} void text(int i,const std::string& v){sqlite3_bind_text(p,i,v.c_str(),-1,SQLITE_TRANSIENT);} void num(int i,int v){sqlite3_bind_int(p,i,v);} };
std::string ask(const std::string& s){std::cout<<s;std::string v;std::getline(std::cin,v);return v;}
std::string upper(std::string s){for(char& c:s)c=static_cast<char>(std::toupper(static_cast<unsigned char>(c)));return s;}
std::string now(){auto t=std::time(nullptr);std::tm tm{};
#ifdef _WIN32
 localtime_s(&tm,&t);
#else
 localtime_r(&t,&tm);
#endif
 char b[32];std::strftime(b,sizeof b,"%Y-%m-%d %H:%M:%S",&tm);return b;}
int count(sqlite3* d,const char* q){Stmt s(d,q);sqlite3_step(s.p);return sqlite3_column_int(s.p,0);}
void dashboard(Db& d){auto x=d.get();std::cout<<"\n=== PARKING OPERATIONS DASHBOARD ===\nSlots: "<<count(x,"SELECT count(*) FROM parking_slots WHERE is_enabled=1")<<" | Available: "<<count(x,"SELECT count(*) FROM parking_slots WHERE is_enabled=1 AND status='available'")<<" | Occupied: "<<count(x,"SELECT count(*) FROM parking_slots WHERE status='occupied'")<<"\nVehicles parked: "<<count(x,"SELECT count(*) FROM parking_transactions WHERE transaction_status='active'")<<"\n";Stmt s(x,"SELECT COALESCE(SUM(parking_fee),0) FROM parking_transactions WHERE payment_status='paid' AND date(exit_time)=date('now','localtime')");sqlite3_step(s.p);std::cout<<"Revenue today: ₱"<<sqlite3_column_int64(s.p,0)/100<<".\n\n";}
void vehicles(Db& d){std::cout<<"1 Register  2 Search/list\n";auto c=ask("> ");auto*x=d.get();if(c=="1"){auto plate=upper(ask("Plate: ")), owner=ask("Owner: "), contact=ask("Contact: "), type=ask("Type (Motorcycle/Sedan/SUV/Van/Pickup Truck): ");if(plate.empty()||owner.empty()||contact.empty())throw std::runtime_error("Plate, owner and contact are required");Stmt s(x,"INSERT INTO vehicles(license_plate,owner_name,contact_number,vehicle_type) VALUES(?,?,?,?)");s.text(1,plate);s.text(2,owner);s.text(3,contact);s.text(4,type);if(sqlite3_step(s.p)!=SQLITE_DONE)throw std::runtime_error(sqlite3_errmsg(x));std::cout<<"Vehicle registered.\n";}else{Stmt s(x,"SELECT vehicle_id,license_plate,owner_name,vehicle_type FROM vehicles ORDER BY license_plate");while(sqlite3_step(s.p)==SQLITE_ROW)std::cout<<sqlite3_column_int(s.p,0)<<"  "<<sqlite3_column_text(s.p,1)<<"  "<<sqlite3_column_text(s.p,2)<<"  "<<sqlite3_column_text(s.p,3)<<"\n";}}
void slots(Db&d){std::cout<<"1 Add slot  2 List slots\n";auto c=ask("> ");auto*x=d.get();if(c=="1"){auto n=ask("Slot number: "),level=ask("Level/section: "),type=ask("Slot type (Motorcycle/Car/SUV/Reserved): ");Stmt s(x,"INSERT INTO parking_slots(slot_number,parking_level,slot_type) VALUES(?,?,?)");s.text(1,n);s.text(2,level);s.text(3,type);if(sqlite3_step(s.p)!=SQLITE_DONE)throw std::runtime_error(sqlite3_errmsg(x));std::cout<<"Slot added.\n";}else{Stmt s(x,"SELECT slot_number,parking_level,slot_type,status,is_enabled FROM parking_slots ORDER BY slot_number");while(sqlite3_step(s.p)==SQLITE_ROW)std::cout<<sqlite3_column_text(s.p,0)<<"  "<<sqlite3_column_text(s.p,1)<<"  "<<sqlite3_column_text(s.p,2)<<"  "<<sqlite3_column_text(s.p,3)<<"  "<<(sqlite3_column_int(s.p,4)?"enabled":"disabled")<<"\n";}}
int vehicleId(sqlite3*x,const std::string&p){Stmt s(x,"SELECT vehicle_id FROM vehicles WHERE license_plate=?");s.text(1,upper(p));if(sqlite3_step(s.p)!=SQLITE_ROW)throw std::runtime_error("Vehicle is not registered");return sqlite3_column_int(s.p,0);}
void entry(Db&d){auto*x=d.get();int id=vehicleId(x,ask("Plate: "));Stmt v(x,"SELECT vehicle_type FROM vehicles WHERE vehicle_id=?");v.num(1,id);sqlite3_step(v.p);std::string type=(const char*)sqlite3_column_text(v.p,0);std::string compatible= type=="Motorcycle"?"Motorcycle":type=="SUV"?"SUV":"Car";d.exec("BEGIN IMMEDIATE");try{Stmt s(x,"SELECT slot_id,slot_number FROM parking_slots WHERE is_enabled=1 AND status='available' AND slot_type IN (?, 'Reserved') ORDER BY slot_number LIMIT 1");s.text(1,compatible);if(sqlite3_step(s.p)!=SQLITE_ROW)throw std::runtime_error("No compatible slots are available");int sid=sqlite3_column_int(s.p,0);std::string sn=(const char*)sqlite3_column_text(s.p,1);Stmt t(x,"INSERT INTO parking_transactions(vehicle_id,slot_id,entry_time) VALUES(?,?,?)");t.num(1,id);t.num(2,sid);t.text(3,now());if(sqlite3_step(t.p)!=SQLITE_DONE)throw std::runtime_error(sqlite3_errmsg(x));int tx=static_cast<int>(sqlite3_last_insert_rowid(x));Stmt u(x,"UPDATE parking_slots SET status='occupied' WHERE slot_id=? AND status='available'");u.num(1,sid);if(sqlite3_step(u.p)!=SQLITE_DONE||sqlite3_changes(x)!=1)throw std::runtime_error("Slot assignment conflict");d.exec("COMMIT");std::cout<<"Entry confirmed. Transaction "<<tx<<", slot "<<sn<<".\n";}catch(...){d.exec("ROLLBACK");throw;}}
void history(Db&d){Stmt s(d.get(),"SELECT t.transaction_id,v.license_plate,p.slot_number,t.entry_time,COALESCE(t.exit_time,'ACTIVE'),COALESCE(t.parking_fee,0),t.payment_status FROM parking_transactions t JOIN vehicles v USING(vehicle_id) JOIN parking_slots p USING(slot_id) ORDER BY t.transaction_id DESC LIMIT 100");std::cout<<"ID  PLATE  SLOT  ENTRY  EXIT  FEE(cents)  PAYMENT\n";while(sqlite3_step(s.p)==SQLITE_ROW)std::cout<<sqlite3_column_int(s.p,0)<<"  "<<sqlite3_column_text(s.p,1)<<"  "<<sqlite3_column_text(s.p,2)<<"  "<<sqlite3_column_text(s.p,3)<<"  "<<sqlite3_column_text(s.p,4)<<"  "<<sqlite3_column_int64(s.p,5)<<"  "<<sqlite3_column_text(s.p,6)<<"\n";}
void revenue(Db&d){auto*x=d.get();const char* labels[]={"Today","This month","All time"};const char* ranges[]={"date(exit_time)=date('now','localtime')","strftime('%Y-%m',exit_time)=strftime('%Y-%m','now','localtime')","1=1"};for(int i=0;i<3;++i){std::string q="SELECT COALESCE(SUM(parking_fee),0),COUNT(*) FROM parking_transactions WHERE payment_status='paid' AND transaction_status='completed' AND "+std::string(ranges[i]);Stmt s(x,q.c_str());sqlite3_step(s.p);std::cout<<labels[i]<<": ₱"<<sqlite3_column_int64(s.p,0)/100<<"."<<std::setw(2)<<std::setfill('0')<<sqlite3_column_int64(s.p,0)%100<<std::setfill(' ')<<" ("<<sqlite3_column_int(s.p,1)<<" transactions)\n";}}
void settings(Db&d){auto*x=d.get();std::cout<<"Rates are stored in centavos per hour. Vehicle type (Motorcycle/Car/SUV/Van/Pickup Truck): ";auto type=ask("");std::cout<<"Initial fee (whole pesos): ";auto a=ask("");std::cout<<"Additional started hour (whole pesos): ";auto b=ask("");try{int initial=std::stoi(a),additional=std::stoi(b);if(initial<0||additional<0)throw std::runtime_error("Rates must be zero or greater");std::string key="rate."+type;Stmt s(x,"INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value");s.text(1,key);s.text(2,std::to_string(initial*100)+","+std::to_string(additional*100));if(sqlite3_step(s.p)!=SQLITE_DONE)throw std::runtime_error(sqlite3_errmsg(x));std::cout<<"Rate saved. (The exit workflow currently uses sample defaults.)\n";}catch(const std::exception&e){std::cout<<"Invalid rate: "<<e.what()<<"\n";}}
void exitVehicle(Db&d){auto*x=d.get();auto plate=upper(ask("Plate: "));Stmt s(x,"SELECT t.transaction_id,t.slot_id,t.entry_time,v.vehicle_type FROM parking_transactions t JOIN vehicles v USING(vehicle_id) WHERE v.license_plate=? AND t.transaction_status='active'");s.text(1,plate);if(sqlite3_step(s.p)!=SQLITE_ROW)throw std::runtime_error("No active session for this plate");int id=sqlite3_column_int(s.p,0),slot=sqlite3_column_int(s.p,1);std::string ts=(const char*)sqlite3_column_text(s.p,2),type=(const char*)sqlite3_column_text(s.p,3);std::tm tm{};std::istringstream in(ts);in>>std::get_time(&tm,"%Y-%m-%d %H:%M:%S");if(in.fail())throw std::runtime_error("Invalid entry timestamp");std::int64_t seconds=std::max<std::int64_t>(0,static_cast<std::int64_t>(std::time(nullptr)-std::mktime(&tm)));parking::Rate rate=type=="Motorcycle"?parking::Rate{2000,1000}:type=="SUV"?parking::Rate{5000,2500}:type=="Van"||type=="Pickup Truck"?parking::Rate{6000,3000}:parking::Rate{4000,2000};auto cents=parking::FeeCalculator::fee(type,seconds,rate);std::cout<<"Duration "<<seconds/3600<<"h "<<(seconds%3600)/60<<"m; fee ₱"<<cents/100<<"."<<std::setw(2)<<std::setfill('0')<<cents%100<<std::setfill(' ')<<". Confirm payment (y/N)? ";if(ask("")!="y")return;d.exec("BEGIN IMMEDIATE");try{Stmt u(x,"UPDATE parking_transactions SET exit_time=?,parking_duration=?,parking_fee=?,payment_status='paid',transaction_status='completed' WHERE transaction_id=? AND transaction_status='active'");u.text(1,now());u.num(2,static_cast<int>(seconds));sqlite3_bind_int64(u.p,3,cents);u.num(4,id);if(sqlite3_step(u.p)!=SQLITE_DONE||sqlite3_changes(x)!=1)throw std::runtime_error("Session already completed");Stmt q(x,"UPDATE parking_slots SET status='available' WHERE slot_id=? AND status='occupied'");q.num(1,slot);if(sqlite3_step(q.p)!=SQLITE_DONE||sqlite3_changes(x)!=1)throw std::runtime_error("Slot state mismatch");d.exec("COMMIT");}catch(...){d.exec("ROLLBACK");throw;}std::cout<<"Exit and payment recorded.\n";}
}
int main(){try{std::filesystem::create_directories("data");Db d("data/parking.db");d.exec("CREATE TABLE IF NOT EXISTS parking_slots(slot_id INTEGER PRIMARY KEY,slot_number TEXT UNIQUE NOT NULL,parking_level TEXT NOT NULL,slot_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',is_enabled INTEGER NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS vehicles(vehicle_id INTEGER PRIMARY KEY,license_plate TEXT UNIQUE NOT NULL,owner_name TEXT NOT NULL,contact_number TEXT NOT NULL,vehicle_type TEXT NOT NULL,vehicle_description TEXT NOT NULL DEFAULT '',registration_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS parking_transactions(transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,vehicle_id INTEGER NOT NULL REFERENCES vehicles(vehicle_id),slot_id INTEGER NOT NULL REFERENCES parking_slots(slot_id),entry_time TEXT NOT NULL,exit_time TEXT,parking_duration INTEGER,parking_fee INTEGER,payment_status TEXT NOT NULL DEFAULT 'unpaid',transaction_status TEXT NOT NULL DEFAULT 'active');CREATE UNIQUE INDEX IF NOT EXISTS one_active_vehicle ON parking_transactions(vehicle_id) WHERE transaction_status='active';CREATE UNIQUE INDEX IF NOT EXISTS one_active_slot ON parking_transactions(slot_id) WHERE transaction_status='active';CREATE TABLE IF NOT EXISTS settings(setting_id INTEGER PRIMARY KEY,setting_key TEXT UNIQUE NOT NULL,setting_value TEXT NOT NULL);");
 bool run=true;while(run){try{std::cout<<"\n╔════════ C++ PARKING MANAGEMENT ════════╗\n1 Dashboard  2 Vehicles  3 Slots  4 Vehicle entry\n5 Vehicle exit  6 History  7 Revenue  8 Settings  9 Quit\n";auto c=ask("> ");if(c=="1")dashboard(d);else if(c=="2")vehicles(d);else if(c=="3")slots(d);else if(c=="4")entry(d);else if(c=="5")exitVehicle(d);else if(c=="6")history(d);else if(c=="7")revenue(d);else if(c=="8")settings(d);else if(c=="9")run=false;else std::cout<<"Choose a menu option from 1 to 9.\n";}catch(const std::exception&e){std::cout<<"Error: "<<e.what()<<"\n";}}return 0;}catch(const std::exception&e){std::cerr<<"Fatal: "<<e.what()<<"\n";return 1;}}
